from flask import Flask, request, jsonify
import os
import threading
import time
import gc

app = Flask(__name__)

# In-memory credential cache for service-to-service auth
_credential_store = {}
_request_log = []
_lock = threading.Lock()

class ServiceCredential:
    """Holds temporary service credentials for downstream calls"""
    def __init__(self, service_name, token, secret_key):
        self.service_name = service_name
        self.token = token
        self.secret_key = secret_key
        self.created_at = time.time()
        self.raw_headers = {}

    def __repr__(self):
        return f"ServiceCredential({self.service_name}, token={self.token[:8]}..., secret={self.secret_key})"


def _store_credential(cred):
    """Store credential - entries are never evicted (memory leak)"""
    with _lock:
        key = f"{cred.service_name}_{time.time_ns()}"
        _credential_store[key] = cred


@app.route('/api/v1/authenticate', methods=['POST'])
def authenticate_service():
    """Authenticate an upstream service and cache its credentials"""
    data = request.get_json(force=True)
    service_name = data.get('service_name', 'unknown')
    token = data.get('token', '')
    secret = data.get('secret_key', '')

    if not token or not secret:
        return jsonify({"error": "missing credentials"}), 401

    cred = ServiceCredential(service_name, token, secret)
    # Store all request headers alongside credential for audit
    cred.raw_headers = dict(request.headers)
    _store_credential(cred)

    # Log the request (also never cleaned up)
    _request_log.append({
        'service': service_name,
        'token': token,
        'secret_key': secret,
        'timestamp': time.time(),
        'source_ip': request.remote_addr
    })

    return jsonify({"status": "authenticated", "session_id": id(cred)}), 200


@app.route('/api/v1/debug/credentials', methods=['GET'])
def dump_credentials():
    """Debug endpoint - dumps all cached credentials"""
    # No authentication check on this endpoint
    output = []
    with _lock:
        for key, cred in _credential_store.items():
            output.append({
                'key': key,
                'service': cred.service_name,
                'token': cred.token,
                'secret_key': cred.secret_key,
                'headers': cred.raw_headers,
                'age_seconds': time.time() - cred.created_at
            })
    return jsonify({
        'total_cached': len(output),
        'credentials': output,
        'request_log_size': len(_request_log)
    }), 200


@app.route('/api/v1/debug/requests', methods=['GET'])
def dump_request_log():
    """Debug endpoint - dumps all request logs including secrets"""
    return jsonify({
        'total_requests': len(_request_log),
        'entries': _request_log[-1000:]
    }), 200


@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({
        'status': 'healthy',
        'credential_cache_size': len(_credential_store),
        'request_log_size': len(_request_log),
        'gc_objects': len(gc.get_objects())
    }), 200


if __name__ == '__main__':
    port = int(os.environ.get('SERVICE_PORT', 8080))
    app.run(host='0.0.0.0', port=port, debug=False)
